"""Conteúdo editorial dos 28 passeios. Preserva fotos já baixadas ao reconstruir o JSON."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
path=ROOT/'guides.json'
previous=json.loads(path.read_text(encoding='utf-8')) if path.exists() else {}
guides={}
def g(key,title,city,kicker,intro,history,stops,tips,arrival,duration,booking,access,photo_tip,photos,sources):
    guides[key]={'key':key,'title':title,'city':city,'kicker':kicker,'intro':intro,'history':history.split('|'),'stops':[{'title':t,'text':x} for t,x in stops],'tips':tips,'arrival':arrival,'duration':duration,'booking':booking,'accessibility':access,'photo_tip':photo_tip,'photo_titles':photos,'photos':previous.get(key,{}).get('photos',[]),'sources':[{'title':t,'url':u} for t,u in sources],'reviewed':'2026-10-24'}

g('roma-centro','Primeiro passeio: centro histórico','Roma','Água, pedra e vida nas praças',
'Uma primeira caminhada para sentir Roma sem pressa: fontes barrocas, fachadas em tons quentes e a escadaria que liga a cidade ao Pincio. O passeio cabe na tarde da chegada e pode ser encurtado conforme o cansaço.',
'A Fontana di Trevi transforma o término de um antigo sistema de abastecimento de água em um grande cenário barroco. O projeto de Nicola Salvi foi concluído no século XVIII: a fachada, as rochas e as figuras marinhas fazem a água parecer parte de um teatro.|Na Piazza di Spagna, a fonte da Barcaccia e a escadaria de Trinità dei Monti revelam outra escala de Roma: um espaço de encontro entre ruas comerciais e a colina. Observar os dois lugares em sequência ajuda a perceber como a cidade usa desníveis e água para criar perspectivas.',
[('Fontana di Trevi','Observe a figura central, os cavalos e o contraste entre pedra esculpida e água. Procure a vista da praça antes de se aproximar do nível inferior.'),('Piazza di Spagna','Contorne a Barcaccia para apreciar sua forma de embarcação. A escadaria é o pano de fundo; a subida é opcional no primeiro dia.'),('Via del Corso e ruas laterais','Faça a ligação caminhando por trechos curtos, com uma pausa para café e tempo para se orientar no centro.')],
['Comece depois de deixar as malas e almoçar; o descanso da chegada tem prioridade.','Consulte as regras atuais de acesso ao perímetro da fonte e de uso da escadaria.','Evite reunir o grupo nos pontos de passagem; combine um encontro em uma rua lateral.'],
'Referência de chegada: estação Barberini ou Spagna; confirme a rota a partir do hotel.','2 a 3 horas, ritmo leve','Consulte o acesso oficial da Fontana di Trevi; não confunda a praça com o perímetro controlado da fonte.','Há calçamento irregular, multidões e escadas; a praça pode ser apreciada sem subir até Trinità dei Monti.','Fotografe Trevi pelas laterais da praça e a Barcaccia em um enquadramento mais baixo, sem bloquear a circulação.',
['Trevi Fountain','Spanish Steps'],[('Fontana di Trevi — site oficial','https://www.fontanaditrevi.roma.it/en'),('Piazza di Spagna — Turismo Roma','https://www.turismoroma.it/it/luoghi/piazza-di-spagna')])

g('roma-coliseu','Coliseu, Fórum Romano e Palatino','Roma','Dentro do mundo romano',
'Um percurso entre espetáculo, política e poder imperial. A manhã combina o anfiteatro com as ruínas do centro cívico de Roma e as vistas do Palatino.',
'O Coliseu foi erguido no século I pela dinastia Flávia para receber espetáculos públicos, incluindo combates de gladiadores. A organização de corredores, arquibancadas e acessos mostra a capacidade da engenharia romana de administrar multidões.|O Fórum era o centro de decisões, cerimônias e vida pública da cidade. No Palatino, as residências imperiais traduziram o poder em arquitetura. Percorrer esses espaços em conjunto permite ir além da imagem isolada do Coliseu e entender a relação entre governantes, população e paisagem urbana.',
[('Coliseu','Identifique os níveis de arcos e observe a arena a partir do percurso permitido pelo seu ingresso. Subsolo e áreas especiais dependem da modalidade adquirida.'),('Fórum Romano','Use a Via Sacra como fio condutor e relacione arcos, templos e basílicas às funções da cidade antiga.'),('Palatino','Reserve energia para as subidas e para os mirantes sobre o Fórum. Escolha um ponto de pausa para comparar o sítio com um mapa histórico.')],
['Marque o Coliseu como primeiro compromisso com horário fixo e deixe margem para a segurança.','Um guia credenciado ou audioguia ajuda a interpretar as ruínas; escolha idioma antes de comprar.','Leve água e calçado firme; planeje almoço e descanso antes do passeio da tarde.'],
'Referência: estação Colosseo. Confira no ingresso o portão de entrada de cada área.','3 a 4 horas','Escolha o ingresso no portal oficial e confira áreas incluídas, identificação exigida e regras de entrada.','O sítio tem trechos irregulares e desníveis; consulte os percursos acessíveis do parque antes da visita.','Use o mirante do Palatino para uma vista ampla do Fórum; evite subir em estruturas arqueológicas.',
['Colosseum','Roman Forum','Palatine Hill'],[('Coliseu — história e visita','https://colosseo.it/en/area/the-colosseum/'),('Fórum Romano','https://colosseo.it/en/area/the-roman-forum/'),('Ingressos e horários oficiais','https://colosseo.it/en/opening-times-and-tickets/')])

g('roma-campidoglio','Campidoglio e Piazza Venezia','Roma','Duas ideias de cidade monumental',
'Uma caminhada curta em distância, mas rica em camadas históricas: da praça renascentista desenhada por Michelangelo à escala do monumento dedicado à unificação italiana.',
'A colina Capitolina ocupa um lugar central na história política de Roma. No Renascimento, Michelangelo reorganizou a praça do Campidoglio como um conjunto coerente de fachadas, acessos e perspectiva, reinterpretando um espaço de origem antiga.|A vizinha Piazza Venezia apresenta uma Roma mais recente. O Vittoriano, dedicado a Vittorio Emanuele II, pertence ao imaginário da Itália unificada. A proximidade desses cenários permite comparar como épocas diferentes representaram a autoridade na cidade.',
[('Cordonata e praça do Campidoglio','Suba pela rampa monumental quando viável e observe como o espaço se abre entre os palácios.'),('Marco Aurélio e palácios','A estátua equestre na praça é uma reprodução; o original integra os Museus Capitolinos. Compare os eixos e a composição das fachadas.'),('Piazza Venezia e Vittoriano','Aprecie o monumento pelo exterior e escolha apenas um complemento interno ou mirante, se houver tempo e disponibilidade.')],
['O passeio da manhã já terá exigido caminhada: faça uma pausa antes da subida.','Museus Capitolinos e terraços são visitas independentes; não os trate como automaticamente incluídos.','Use travessias sinalizadas ao redor de Piazza Venezia e confira desvios locais.'],
'Chegue a pé a partir da região do Fórum; referência de destino: Piazza del Campidoglio.','1h30 a 2h30','A praça é um passeio externo; museus e acessos especiais devem ser consultados nos sites oficiais.','Há ladeiras, degraus e ruas movimentadas; consulte o acesso alternativo dos museus se necessário.','Enquadre a praça da chegada da Cordonata e procure o panorama do Fórum atrás do Palazzo Senatorio.',
['Piazza del Campidoglio','Victor Emmanuel II Monument'],[('Museus Capitolinos','https://www.museicapitolini.org/en'),('Vittoriano — instituição oficial','https://vive.cultura.gov.it/en')])

g('vaticano-museus','Museus Vaticanos e Capela Sistina','Roma','Arte que transforma o olhar',
'Uma manhã de grandes coleções, corredores monumentais e pintura renascentista. O segredo é selecionar um percurso, em vez de tentar ver tudo.',
'Os Museus Vaticanos reúnem coleções formadas ao longo de séculos sob o patrocínio dos papas. Esculturas antigas, mapas e salas decoradas revelam o diálogo entre o mundo clássico e a cultura cristã.|A Capela Sistina recebe o nome de Sisto IV. Sua decoração envolve artistas do século XV e as intervenções de Michelangelo: o teto, concluído em 1512, e o Juízo Final, realizado mais tarde. As pinturas fazem parte de uma capela em uso religioso, não apenas de uma sala de museu.',
[('Coleções clássicas','Selecione algumas esculturas e observe como os artistas do Renascimento retomaram os modelos antigos.'),('Galeria dos Mapas e salas decoradas','Compare o caráter científico dos mapas com a exuberância de tetos e paredes; siga o fluxo indicado pelo museu.'),('Capela Sistina','Reserve um momento de silêncio para olhar o teto e a parede do altar. As regras de fotografia e comportamento devem ser respeitadas.')],
['Compre no portal oficial e confirme o idioma se optar por guia ou audioguia.','Não programe o grupo para se separar sem definir ponto de reencontro: o percurso é extenso.','Use roupas adequadas aos espaços religiosos e confira o tamanho permitido de bolsas.'],
'A entrada dos museus fica no Viale Vaticano; não é a entrada da Basílica de São Pedro.','3 a 4 horas','Reserva recomendada pelo portal oficial; confirme o calendário da data e a modalidade de visita.','Solicite informação sobre percurso acessível e elevadores: ele pode diferir do itinerário comum.','Fotografe apenas onde permitido. Na Capela Sistina, guarde a câmera e concentre-se na observação.',
['Vatican Museums','Sistine Chapel'],[('História da Capela Sistina','https://www.museivaticani.va/content/museivaticani/en/collezioni/musei/cappella-sistina/storia-cappella-sistina.html'),('Informações e regras de visita','https://www.museivaticani.va/content/museivaticani/en/organizza-visita.html'),('Ingressos oficiais','https://tickets.museivaticani.va/')])

g('vaticano-saopedro','Praça e Basílica de São Pedro','Roma','A escala do encontro',
'Do abraço arquitetônico da praça ao interior monumental da basílica, uma visita para observar arte, espaço e tradição religiosa com tempo e respeito.',
'A atual Basílica de São Pedro foi construída sobre uma longa tradição de culto ligada ao apóstolo Pedro, substituindo a basílica da época de Constantino. Seu desenvolvimento reuniu gerações de arquitetos e artistas, entre eles Michelangelo e Bernini.|A praça de Bernini organiza a chegada por meio de grandes colunatas. No interior, esculturas, mosaicos e o baldaquino criam referências dentro de uma arquitetura de escala extraordinária. É importante distinguir a visita cultural das celebrações que continuam a orientar a vida do local.',
[('Praça e colunatas','Caminhe pelo contorno da praça e observe como as colunas mudam de alinhamento conforme a posição do visitante.'),('Nave e obras de arte','Procure a Pietà de Michelangelo e observe o baldaquino de Bernini sem interromper áreas de oração.'),('Cúpula, opcional','A subida é uma atividade à parte, com condições físicas e acesso específicos. Só inclua se houver energia depois dos museus.')],
['Faça uma pausa para almoço entre os museus e a basílica.','Confirme celebrações, acessos e vestimenta antes de sair do hotel.','Não conte com passagem direta dos museus para a basílica; planeje o trajeto permitido.'],
'Referência de chegada: Piazza San Pietro. Preveja fila e controle de segurança.','1h30 a 2h30; cúpula exige tempo adicional','Consulte serviços oficiais, reservas e regras de visita. Museu, cúpula e experiências especiais podem ter condições próprias.','O percurso da basílica e o da cúpula têm exigências diferentes; confirme adaptações disponíveis.','Faça uma foto ampla da praça e fotografe o interior somente onde permitido, sem flash e sem interferir nas celebrações.',
["St. Peter's Basilica","St. Peter's Square"],[('Basílica de São Pedro — site oficial','https://www.basilicasanpietro.va/en'),('Visita virtual oficial','https://virtual.basilicasanpietro.va/')])

g('roma-pantheon','Pantheon, Piazza Navona e Campo de’ Fiori','Roma','Da Roma antiga à cidade barroca',
'Um percurso a pé entre uma cúpula romana extraordinária, uma praça que conserva a forma de um estádio antigo e ruas de comércio e convivência.',
'O Pantheon preserva uma das experiências espaciais mais marcantes da arquitetura romana: uma grande cúpula iluminada pelo óculo central. O edifício antigo foi convertido em igreja, o que ajuda a explicar sua permanência e a convivência de usos ao longo do tempo.|A Piazza Navona ocupa a área do antigo estádio de Domiciano. A forma alongada sobrevive na praça barroca, transformada por fontes e fachadas. Campo de’ Fiori oferece outro tipo de memória urbana: uma praça de mercado e encontro marcada pela estátua de Giordano Bruno.',
[('Pantheon','Observe o pórtico antes de entrar. No interior, acompanhe a luz do óculo e a relação entre cúpula e espaço circular.'),('Piazza Navona','Percorra a extensão da praça e compare a Fontana dei Quattro Fiumi com as outras fontes e a fachada de Sant’Agnese.'),('Campo de’ Fiori','Encerre pelas ruas próximas e escolha uma pausa para almoço; o aspecto da praça muda ao longo do dia.')],
['Reserve a entrada do Pantheon conforme o calendário oficial.','Leve um mapa e conecte os pontos pelas ruas menores, sem transformar o passeio em corrida.','Na visita à igreja, respeite vestimenta, silêncio e orientações do pessoal.'],
'Comece na Piazza della Rotonda e siga a pé por Navona até Campo de’ Fiori.','2h30 a 3 horas','O Pantheon tem ingresso e regras próprios; as praças são trechos externos do passeio.','Calçamento de pedra, pequenas irregularidades e trechos cheios; confira o acesso adaptado do Pantheon.','Registre o óculo sem flash e procure um enquadramento que mostre a extensão de Piazza Navona.',
['Pantheon, Rome','Piazza Navona',"Campo de' Fiori"],[('Pantheon — Museu oficial','https://direzionemuseiroma.cultura.gov.it/en/pantheon/'),('Piazza Navona — Turismo Roma','https://www.turismoroma.it/it/luoghi/piazza-navona'),('Campo de’ Fiori — Turismo Roma','https://www.turismoroma.it/it/luoghi/campo-de%E2%80%99-fiori')])

g('roma-trastevere','Trastevere ao entardecer','Roma','A cidade na escala das ruas',
'Uma tarde para desacelerar entre fachadas, pequenas praças e uma mesa compartilhada. O bairro funciona melhor como descoberta a pé do que como sequência de atrações com horário marcado.',
'O nome Trastevere remete à posição do bairro do outro lado do Tibre em relação ao núcleo antigo de Roma. A região conserva uma rede de ruas estreitas e praças que se contrapõe às grandes vias monumentais.|A Basílica de Santa Maria in Trastevere é uma referência histórica e artística do bairro, com mosaicos que merecem uma visita atenta quando o espaço estiver aberto. Ao redor, a vida de moradores e visitantes se mistura; a experiência ganha com respeito ao silêncio e às rotinas locais.',
[('Ponte e chegada ao bairro','Escolha uma travessia sobre o Tibre e observe a mudança de escala ao entrar nas ruas menores.'),('Piazza Santa Maria in Trastevere','Use a praça como referência para o grupo. Visite a basílica, se aberta, observando o ambiente religioso.'),('Ruas e jantar em grupo','Faça um circuito curto e encerre em restaurante escolhido com antecedência, conferindo o cardápio e as condições do grupo.')],
['Reserve o jantar se o grupo for grande; não há restaurante já contratado.','Use calçado confortável no piso de pedra.','Prefira um percurso curto e evite falar alto junto às residências à noite.'],
'Referência: Piazza Santa Maria in Trastevere; confirme ônibus ou caminhada a partir do passeio anterior.','2 a 3 horas, incluindo pausas','Caminhada externa sem reserva; igrejas e restaurantes têm regras próprias.','Há pavimento irregular e ruas estreitas; selecione uma rota com menos desníveis conforme o grupo.','Procure a luz nas fachadas antes de escurecer e evite fotografar pessoas de perto sem autorização.',
['Trastevere','Santa Maria in Trastevere'],[('Santa Maria in Trastevere — Turismo Roma','https://www.turismoroma.it/it/luoghi/basilica-di-santa-maria-trastevere'),('Roteiro turístico de Roma','https://www.turismoroma.it/it/itinerari/roma-72-ore')])

g('roma-borghese','Villa Borghese e Pincio','Roma','Um último olhar sobre Roma',
'Jardins, caminhos arborizados e um panorama sobre a cidade antes do deslocamento para Paris. A proposta é ficar ao ar livre e terminar com folga para o voo das 18h.',
'Villa Borghese se desenvolveu a partir da propriedade da família Borghese e de seu conjunto de edifícios, jardins e coleções. A antiga paisagem de lazer aristocrático passou a integrar a vida pública da cidade no início do século XX.|O Pincio consolidou-se como passeio urbano e mirante, com caminhos e terraços voltados para Piazza del Popolo. A conexão entre parque e belvedere oferece uma leitura de Roma que contrasta com os monumentos visitados nos dias anteriores.',
[('Caminhos de Villa Borghese','Escolha um trecho de jardim e mantenha o percurso simples; o parque é extenso.'),('Terraço do Pincio','Observe Piazza del Popolo e procure a cúpula de São Pedro no horizonte.'),('Saída organizada','Defina o ponto de encontro para retornar ao hotel, recolher as malas e seguir ao aeroporto.')],
['Não encaixe a Galleria Borghese sem reserva e sem recalcular o tempo do traslado.','Leve uma camada extra para a manhã de novembro.','Interrompa o passeio se o horário de saída do hotel exigir mais antecedência.'],
'Referências: entrada próxima a Porta Pinciana ou região de Piazza del Popolo.','2 a 3 horas, com limite definido pelo traslado','O passeio proposto é nos jardins; a Galleria Borghese é visita separada com reserva.','Há caminhos em terra, inclinações e acessos por escadas; escolha entrada e saída adequadas ao grupo.','Do Pincio, componha a praça em primeiro plano e a cidade ao fundo, sem subir no parapeito.',
['Villa Borghese gardens','Pincian Hill'],[('Villa Borghese — patrimônio municipal','https://www.sovraintendenzaroma.it/i_luoghi/ville_e_parchi_storici/ville_dei_nobili/villa_borghese'),('Pincio — Turismo Roma','https://www.turismoroma.it/it/luoghi/terrazza-e-passeggiata-del-pincio')])

g('paris-eiffel','Trocadéro, Torre Eiffel e Champ de Mars','Paris','A Paris que chega pelo horizonte',
'Um primeiro passeio parisiense entre o mirante do Trocadéro, a estrutura da Torre Eiffel e os jardins do Champ de Mars. A subida à torre é opcional e depende de ingresso.',
'A Torre Eiffel foi construída para a Exposição Universal de 1889 e se tornou um símbolo da engenharia em ferro e da cidade de Paris. Uma estrutura inicialmente ligada a um evento temporário passou a marcar de forma permanente a paisagem urbana.|A aproximação a partir do Trocadéro permite observar a torre em conjunto com o rio e os espaços abertos. No Champ de Mars, o olhar muda: a escala da estrutura e seus detalhes ficam mais evidentes conforme o visitante se aproxima dos pilares.',
[('Trocadéro','Comece pelo panorama e procure uma posição lateral menos congestionada para reunir o grupo.'),('Torre Eiffel','Observe a trama metálica e os quatro pilares. Se houver ingresso, siga a entrada e o horário indicados na reserva.'),('Champ de Mars','Termine com uma caminhada pelo eixo dos jardins e uma pausa, respeitando eventuais áreas interditadas.')],
['Compre subida apenas no site oficial ou com operador identificado e confira qual pavimento está incluído.','Deixe margem para o controle de segurança; não marque outro compromisso imediatamente depois.','Vista-se para vento e frio nos espaços abertos.'],
'Referência de chegada: Trocadéro. Para a torre, confirme o acesso de pedestres indicado na reserva.','2 a 3 horas pelo exterior; subida exige tempo adicional','A torre tem reservas, categorias e disponibilidade próprios. Não há ingresso incluído no roteiro.','O circuito externo e os diferentes níveis da torre têm condições distintas; consulte acessibilidade oficial.','A vista do Trocadéro funciona para panorama; no Champ de Mars, procure detalhes da estrutura e linhas de perspectiva.',
['Eiffel Tower','Champ de Mars'],[('História da Torre Eiffel','https://www.toureiffel.paris/en/the-monument/history'),('Planeje a visita oficial','https://www.toureiffel.paris/en')])

g('paris-sena','Caminhada às margens do Sena','Paris','A cidade contada pelo rio',
'Um percurso sem pressa junto à água, com pontes e fachadas como referências. A caminhada pode ser reduzida conforme o clima; o cruzeiro é um complemento opcional.',
'O Sena estrutura a história de Paris: suas ilhas, travessias e margens ajudaram a organizar comércio, circulação e expansão urbana. A paisagem reúne monumentos de épocas diferentes e permite observar a cidade por uma linha contínua.|Caminhar pelas margens revela relações que passam despercebidas em deslocamentos de metrô: pontes conectam bairros, fachadas dialogam com o rio e o espaço público oferece novos usos de convivência. A visita é mais interessante quando se escolhe um trecho do que quando se tenta percorrer tudo.',
[('Escolha do trecho','Use a região da Torre Eiffel como início e siga até uma ponte previamente definida, conforme a disposição do grupo.'),('Pontes e perspectivas','Pare fora da faixa de circulação para observar a sequência das travessias e os enquadramentos dos monumentos.'),('Pausa ou cruzeiro','Encerre com uma pausa em terra ou, se o grupo quiser, um passeio de barco reservado separadamente.')],
['Verifique clima e condições de acesso às margens no dia.','Na chuva ou no frio intenso, reduza o circuito e escolha uma pausa coberta.','Se optar por barco, confira cais de embarque, duração e condições de cancelamento.'],
'Comece no trecho próximo à Torre Eiffel e defina a estação de retorno antes de descer ao rio.','1h30 a 2 horas','Caminhada externa; cruzeiros e atrações das margens exigem contratação separada.','Algumas descidas têm escadas e superfícies irregulares; procure acessos por rampa e rotas superiores.','Use as curvas do rio e os arcos das pontes como moldura; mantenha distância segura da borda.',
['Pont Neuf','Pont Alexandre III'],[('Margens do Sena — UNESCO','https://whc.unesco.org/en/list/600/'),('Turismo oficial de Paris','https://parisjetaime.com/eng/')])

g('paris-louvre','Museu do Louvre','Paris','Escolher para enxergar melhor',
'Uma manhã para conhecer um dos grandes museus do mundo por um recorte possível. Escolha algumas obras e salas antes de entrar: a visita ganha profundidade quando não vira uma corrida.',
'O Louvre começou como fortaleza medieval, tornou-se residência real e abriu como museu em 1793. A própria arquitetura guarda marcas dessas transformações, dos vestígios defensivos aos grandes pátios e galerias.|Suas coleções atravessam civilizações e períodos artísticos. A Mona Lisa e a Vitória de Samotrácia são referências conhecidas, mas o percurso pode incluir pintura, escultura ou antiguidades conforme o interesse do grupo. A melhor visita é a que relaciona poucas obras com atenção ao contexto.',
[('Chegada e orientação','Confirme a entrada reservada, passe pela segurança e localize guarda-volumes, banheiros e o mapa.'),('Percurso de destaques','Escolha uma ala ou um circuito curto. Defina prioridades e aceite deixar outras coleções para uma próxima visita.'),('O palácio como obra','Observe escadarias, tetos e vistas para os pátios, além das obras expostas. Termine antes da fadiga de museu.')],
['O passeio está em 04/11, quarta-feira; o fechamento semanal habitual é na terça.','Use o mapa oficial para conferir salas abertas e localização das obras no dia.','Combine reencontro fora das áreas mais disputadas e faça uma pausa após a visita.'],
'Referências: Palais Royal–Musée du Louvre e acessos indicados no ingresso.','3 a 4 horas','Reserve horário e confirme condições no portal oficial; exposições e áreas podem ter restrições próprias.','O museu oferece rotas e serviços adaptados; planeje elevadores e deslocamentos com o mapa oficial.','Fotografe apenas onde autorizado, sem flash, e evite permanecer diante de obras disputadas só para fazer fotos.',
['Louvre','Louvre Pyramid'],[('História do palácio — Louvre','https://www.louvre.fr/en/explore/the-palace'),('Horários e ingressos oficiais','https://www.louvre.fr/en/visit/hours-admission')])

g('paris-tuileries','Tuileries e Palais Royal','Paris','Jardins para respirar entre obras',
'Depois do Louvre, uma caminhada por dois espaços de jardim com atmosferas diferentes: a grande perspectiva das Tuileries e a escala mais reservada do Palais Royal.',
'O Jardim das Tuileries se liga à história do antigo palácio real e à tradição francesa de jardins organizados por eixos e perspectivas. Sua posição entre o Louvre e a Place de la Concorde o transforma em uma peça importante da paisagem central de Paris.|O Palais Royal tem origem no palácio de Richelieu e reúne arquitetura, galerias e jardim. A intervenção contemporânea de Daniel Buren no pátio cria um diálogo visual com o conjunto histórico, oferecendo outra maneira de perceber escala, repetição e espaço público.',
[('Eixo das Tuileries','Caminhe por um trecho do eixo principal e observe o alinhamento dos jardins, as esculturas e as vistas.'),('Pausa no jardim','Reserve tempo para sentar e descansar da manhã de museu, sem compromisso de percorrer todas as alamedas.'),('Palais Royal','Explore o pátio das colunas e o jardim, verificando os acessos disponíveis no dia.')],
['Faça uma pausa real, com água e algo para comer, antes de retomar a caminhada.','Não é necessário entrar em outro museu nesta tarde.','Em caso de mau tempo, encurte a visita e procure as galerias cobertas acessíveis.'],
'Comece junto ao Louvre; siga depois em direção ao Palais Royal conforme o mapa local.','1h30 a 2h30','Percurso externo; confira regras e eventuais fechamentos dos jardins.','Predominam trechos planos, mas há piso de areia compactada e acessos que podem variar.','Nas Tuileries, use o eixo das alamedas; no Palais Royal, explore o contraste entre as colunas e as fachadas.',
['Tuileries Garden','Palais-Royal'],[('Tuileries — Louvre','https://www.louvre.fr/en/explore/the-gardens'),('Palais Royal — monumento oficial','https://www.domaine-palais-royal.fr/en')])

g('paris-cite','Île de la Cité e Quartier Latin','Paris','As origens, as ilhas e o saber',
'Uma manhã entre o núcleo histórico de Paris e a margem esquerda. O percurso privilegia o exterior de Notre-Dame, as pontes e as ruas ligadas à vida universitária.',
'A Île de la Cité ocupa um lugar essencial na formação histórica de Paris. A Catedral de Notre-Dame, cuja construção começou na Idade Média, reúne arquitetura gótica, escultura e sucessivas camadas de restauração.|Na margem esquerda, o Quartier Latin se consolidou como região de escolas e universidade. O nome remete ao latim usado no ensino. Caminhar entre os dois espaços permite passar de uma paisagem religiosa e institucional para ruas associadas a livros, debates e vida estudantil.',
[('Notre-Dame e a ilha','Observe a fachada e os portais a partir das áreas abertas. A entrada interna depende das condições oficiais.'),('Travessia para a margem esquerda','Escolha uma ponte com espaço para observar a relação entre a catedral, o rio e os cais.'),('Quartier Latin','Siga por ruas próximas à Sorbonne e faça uma pausa para café, preservando tempo para o passeio da tarde.')],
['Confirme o acesso a Notre-Dame no site oficial; não há reserva incluída.','Sainte-Chapelle é uma visita extra e exige planejamento separado.','Evite acumular igrejas e museus em sequência se o grupo preferir caminhar.'],
'Referência: Cité ou Saint-Michel; confirme a conexão mais conveniente a partir do hotel.','2 a 3 horas','Passeio externo; Notre-Dame e outros monumentos têm regras próprias de acesso.','Pontes, calçadas estreitas e piso de pedra exigem atenção; consulte acessos adaptados dos monumentos.','Procure a catedral vista das pontes e os detalhes das fachadas, respeitando áreas de culto e circulação.',
['Notre-Dame de Paris','Latin Quarter, Paris'],[('Notre-Dame — história e visita','https://www.notredamedeparis.fr/en/'),('Quartier Latin — turismo oficial','https://parisjetaime.com/eng/article/timeless-paris-a897')])

g('paris-luxemburgo','Jardim de Luxemburgo e Saint-Germain','Paris','Jardins, literatura e uma pausa parisiense',
'Uma tarde de passos curtos, bancos de jardim e cafés. É um contraponto leve à manhã na ilha e uma oportunidade de observar a vida cotidiana da margem esquerda.',
'O Jardim de Luxemburgo nasceu ligado ao palácio de Maria de Médici, no século XVII. O conjunto combina áreas formais, esculturas e espaços de lazer, articulando a história do poder com o uso cotidiano dos jardins.|Saint-Germain-des-Prés ganhou destaque cultural por seus círculos literários, artísticos e intelectuais. A visita faz mais sentido como caminhada de observação do que como busca por uma lista de mesas famosas: ruas, igrejas, livrarias e cafés formam o ambiente do bairro.',
[('Bacia central e jardins','Observe o eixo do palácio e escolha um trecho de passeio compatível com o tempo e o clima.'),('Fonte Médici','Procure o ambiente mais recolhido junto à fonte e compare sua atmosfera com a área central.'),('Saint-Germain-des-Prés','Finalize pelas ruas do bairro, com uma pausa em café escolhido pelo grupo e pelo orçamento.')],
['Confirme o horário de fechamento do jardim para novembro.','A visita proposta não inclui o interior do palácio ou do Senado.','Em dia frio, distribua o passeio em trechos curtos com uma parada coberta.'],
'Comece no Jardim de Luxemburgo e depois siga em direção a Saint-Germain-des-Prés.','2 a 3 horas','Jardim e caminhada de bairro; visitas institucionais têm condições separadas.','Há piso de areia compactada e algumas entradas com desníveis; escolha acessos adequados ao grupo.','Registre o reflexo na Fonte Médici e as alamedas, sem atrapalhar os espaços de descanso.',
['Jardin du Luxembourg','Saint-Germain-des-Prés'],[('Jardim de Luxemburgo — Senado francês','https://jardin.senat.fr/histoire-patrimoine/histoire.html'),('Saint-Germain — turismo de Paris','https://parisjetaime.com/eng/')])

g('paris-versalhes','Versalhes — passeio opcional','Paris','O poder como cenário',
'Um dia fora do centro de Paris para conhecer o palácio e a paisagem de Versalhes. O passeio exige uma escolha de prioridades: palácio, jardins e domínios não cabem todos com a mesma profundidade.',
'Versalhes tornou-se o grande cenário da corte de Luís XIV, articulando residência, governo e representação do poder. A arquitetura, a decoração e a organização dos jardins construíam uma imagem de centralidade e ordem.|A Galeria dos Espelhos é um dos espaços mais conhecidos do palácio. Nos jardins, eixos, perspectivas e bosques prolongam a experiência para além dos interiores. O conjunto também testemunha transformações da monarquia e da história francesa posteriores ao Rei Sol.',
[('Chegada e entrada reservada','Confira a fila correta e guarde tempo para segurança e orientação; o deslocamento desde Paris faz parte do dia.'),('Palácio e Galeria dos Espelhos','Observe a relação entre salas, cerimônia e representação. Use audioguia ou visita oficial se preferir contexto adicional.'),('Jardins e retorno','Escolha um circuito reduzido nos jardins. Só acrescente Trianon se a modalidade de ingresso e o tempo permitirem.')],
['Confirme a modalidade do ingresso e o que ela inclui no dia escolhido.','Verifique transporte e eventuais alterações antes da partida.','Leve roupa para áreas abertas e aceite trocar por um dia em Paris se o clima ou o grupo não favorecerem.'],
'Destino: Château de Versailles. Consulte o trajeto ferroviário atualizado e o trecho a pé até a entrada.','Dia inteiro, incluindo transporte','Reserva no site oficial; palácio, jardins e Trianon podem ter regras e calendários distintos.','O domínio é extenso, com grandes distâncias e pisos variados; consulte serviços adaptados e opções de deslocamento.','Nos jardins, explore os eixos e a perspectiva do palácio. No interior, siga as restrições de fotografia.',
['Palace of Versailles','Hall of Mirrors'],[('Palácio de Versalhes — história','https://en.chateauversailles.fr/discover/estate/palace'),('Planejamento e ingressos','https://en.chateauversailles.fr/plan-your-visit')])

g('paris-montmartre','Montmartre e Sacré-Cœur','Paris','Uma colina, muitos pontos de vista',
'Uma manhã entre mirantes, ruas em ladeira e referências à vida artística de Paris. A basílica coroa a paisagem, mas o bairro merece atenção além da vista panorâmica.',
'Montmartre preserva a memória de uma antiga área de colina que se integrou à expansão parisiense. Ateliês, cabarés e encontros artísticos contribuíram para sua imagem cultural entre o fim do século XIX e o início do XX.|A Basílica do Sacré-Cœur, construída a partir do século XIX, tornou-se um marco visível de muitos pontos da cidade. Sua posição reforça a experiência da subida: a paisagem se abre aos poucos, e a arquitetura religiosa convive com a intensa circulação turística do entorno.',
[('Subida e chegada','Escolha entre caminhada e transporte disponível conforme o grupo; não é necessário fazer todas as escadarias.'),('Sacré-Cœur e mirante','Aprecie o panorama e visite o interior de acordo com as regras da basílica, mantendo silêncio.'),('Place du Tertre e ruas laterais','Faça um circuito pequeno para observar fachadas, ateliês e a escala do bairro além dos pontos mais cheios.')],
['Use sapatos com boa aderência nas ladeiras.','Combine um ponto de encontro claro antes de explorar ruas menores.','Confira as regras de fotografia dentro da basílica e a condição do acesso à cúpula, se desejado.'],
'Referências: Anvers ou Abbesses; escolha a chegada que melhor atende à mobilidade do grupo.','2h30 a 3 horas','Caminhada e basílica têm condições próprias; cúpula e serviços especiais são visitas separadas.','A colina tem desníveis importantes; avalie o funicular e acessos alternativos antes de definir o circuito.','Busque um panorama lateral do mirante e detalhes das ruas; não pare no centro das escadas para fazer fotos.',
['Montmartre','Sacré-Cœur, Paris'],[('Sacré-Cœur — site oficial','https://www.sacre-coeur-montmartre.com/english/'),('Montmartre — turismo de Paris','https://parisjetaime.com/eng/')])

g('paris-opera','Opéra e arredores','Paris','O espetáculo começa na arquitetura',
'Uma tarde no entorno do Palais Garnier, entre fachadas monumentais e grandes eixos urbanos. A visita interna é opcional e precisa ser conciliada com a programação da ópera.',
'Inaugurado em 1875, o Palais Garnier é um marco da arquitetura teatral do século XIX. O projeto de Charles Garnier transforma a chegada, a escadaria e os espaços de convivência em parte da experiência do espetáculo.|O bairro permite observar a Paris das grandes avenidas e do comércio. Mesmo sem entrar na sala de apresentações, a fachada e o entorno ajudam a perceber como a ópera se tornou referência urbana, articulando cultura, circulação e vida social.',
[('Fachada do Palais Garnier','Observe esculturas e a composição do edifício a partir de um ponto seguro da praça.'),('Interior, se reservado','Confira quais áreas estão acessíveis: ensaios e apresentações podem limitar a visita. A escadaria e os salões são os destaques usuais.'),('Ruas comerciais do entorno','Complete o passeio com um circuito curto e uma pausa, sem pressupor acesso a terraços ou espaços privados.')],
['Consulte o calendário oficial antes de reservar visita ou espetáculo.','Visita diurna e ingresso de apresentação são produtos diferentes.','Escolha um trecho curto após Montmartre para evitar uma tarde excessivamente cansativa.'],
'Referência de chegada: estação Opéra e Place de l’Opéra.','2 a 3 horas','Interior sujeito à programação e ao ingresso escolhido; o passeio externo pode ser feito separadamente.','Confirme os acessos e serviços do edifício, especialmente se houver mobilidade reduzida.','Use a fachada para uma composição ampla; no interior, respeite o uso de flash e as áreas restritas.',
["Palais Garnier","Avenue de l'Opéra"],[('Palais Garnier — visita oficial','https://www.operadeparis.fr/en/visits/palais-garnier'),('Opéra national de Paris','https://www.operadeparis.fr/en')])

g('paris-orsay','Musée d’Orsay — visita opcional','Paris','Uma estação transformada em museu',
'Uma visita para quem quer aprofundar a arte do século XIX e do início do XX. O próprio edifício ajuda a compreender a relação entre modernidade, cidade e novas formas de olhar.',
'O Musée d’Orsay ocupa uma antiga estação ferroviária construída para a Exposição Universal de 1900. A transformação em museu preservou a grande nave e reinventou seu uso, fazendo da arquitetura uma parte central da visita.|As coleções permitem acompanhar mudanças na pintura, escultura e artes decorativas, incluindo impressionismo e pós-impressionismo. Em vez de buscar todas as obras famosas, vale selecionar um conjunto e observar como luz, movimento e vida moderna se tornam assuntos da arte.',
[('A grande nave','Comece olhando a estrutura da antiga estação e a organização das esculturas.'),('Um recorte das coleções','Escolha pintura impressionista, pós-impressionista ou outro eixo de interesse e siga a sinalização atual.'),('Relógios e vistas','Procure as vistas permitidas e faça uma pausa antes de seguir para o passeio da tarde.')],
['A visita está proposta para sábado; confirme o calendário e a disponibilidade.','Não use esta manhã para tentar repetir o ritmo do Louvre: mantenha um foco menor.','Se o grupo não quiser outro museu, troque por caminhada curta pelo Sena.'],
'Referência: Musée d’Orsay ou Solférino; confirme o acesso indicado no bilhete.','2 a 3 horas','Reserve no site oficial e confira a modalidade. O fechamento habitual é às segundas-feiras.','Consulte elevadores, entrada adaptada e recursos de visita no portal do museu.','Fotografe a arquitetura e apenas obras autorizadas; não interrompa a fila dos pontos de vista junto aos relógios.',
["Gare d'Orsay","Bal du moulin de la Galette"],[('Musée d’Orsay — visita','https://www.musee-orsay.fr/en/visit'),('História e coleções','https://www.musee-orsay.fr/en')])

g('paris-arco','Champs-Élysées e Arco do Triunfo','Paris','Perspectiva, memória e cidade',
'Uma caminhada pelo eixo de uma das avenidas mais conhecidas de Paris, terminando no monumento que organiza visualmente a Place Charles-de-Gaulle.',
'O Arco do Triunfo foi encomendado por Napoleão no início do século XIX e concluído décadas depois. Seus relevos e inscrições se relacionam à memória militar francesa, enquanto o Túmulo do Soldado Desconhecido acrescenta outra camada de lembrança pública.|A Champs-Élysées faz parte de uma grande perspectiva urbana que conecta jardins, praças e monumentos. Caminhá-la permite observar tanto essa composição histórica quanto a avenida comercial contemporânea. A subida ao terraço muda a leitura do traçado radial das ruas.',
[('Trecho da Champs-Élysées','Escolha apenas parte da avenida conforme a energia do grupo; não é preciso percorrer toda a extensão.'),('Base do Arco','Acesse pela passagem indicada e observe relevos, inscrições e o espaço de memória, respeitando cerimônias.'),('Terraço, opcional','Se houver ingresso e condições de acesso, veja a organização das avenidas a partir do alto.')],
['Use a passagem subterrânea para o monumento; não atravesse a rotatória pela pista.','Consulte condições do terraço e possíveis cerimônias antes da visita.','Mantenha uma alternativa apenas externa se o grupo estiver cansado do museu.'],
'Referência de destino: Charles de Gaulle–Étoile; observe a saída e a passagem correta para o Arco.','2 a 3 horas','Subida e visita interna dependem de ingresso e condições oficiais.','A subida envolve condições específicas; verifique elevador e trechos finais com escadas no site do monumento.','Da base, procure detalhes dos relevos; o terraço oferece vistas das avenidas quando aberto.',
['Arc de Triomphe','Champs-Élysées'],[('Arco do Triunfo — monumento oficial','https://www.paris-arc-de-triomphe.fr/en'),('História do monumento','https://www.paris-arc-de-triomphe.fr/en/discover')])

g('paris-marais','Le Marais e Place des Vosges','Paris','Pátios, praças e ruas com memória',
'Uma despedida de Paris em ritmo de bairro, com tempo para observar arquitetura e fazer uma pausa antes de organizar a saída para Londres.',
'Le Marais conserva uma trama urbana associada a antigas residências aristocráticas e sucessivas transformações da vida parisiense. Seus palacetes, pátios e ruas permitem perceber uma escala diferente das grandes avenidas.|A Place des Vosges, criada no início do século XVII, oferece uma composição regular de fachadas e arcadas ao redor de um jardim. O bairro também reúne importantes camadas de história judaica e de vida cultural contemporânea, que merecem ser tratadas com atenção e respeito.',
[('Place des Vosges','Caminhe sob as arcadas e compare a regularidade das fachadas com o espaço central.'),('Ruas e pátios do Marais','Escolha um circuito curto para observar portais, fachadas e pequenos espaços públicos.'),('Pausa e retorno','Almoce ou faça uma pausa antes de voltar ao hotel para malas e preparação do deslocamento.')],
['Mantenha o restante do dia livre para organizar a saída das 23h.','Se quiser entrar em museu ou casa histórica, consulte o funcionamento específico de domingo.','Evite transformar a manhã em compras longas com bagagens antes do transporte noturno.'],
'Referências: Saint-Paul ou região da Place des Vosges; defina a volta ao hotel com antecedência.','2 a 4 horas, flexível','Caminhada externa; museus e visitas internas devem ser reservados separadamente quando necessário.','Calçadas e lojas podem ter desníveis; o jardim e as arcadas permitem um circuito mais curto.','Explore a repetição das arcadas e os detalhes de portas e fachadas, sem entrar em pátios privados.',
['Rue des Rosiers','Place des Vosges'],[('Place des Vosges — turismo oficial','https://parisjetaime.com/eng/transport/place-des-vosges-p1907'),('Turismo oficial de Paris','https://parisjetaime.com/eng/')])

g('londres-westminster','Westminster, Big Ben e St James’s Park','Londres','Símbolos à beira do Tâmisa',
'Uma primeira leitura de Londres entre Parlamento, abadia e parque. Como a chegada ainda não tem horário confirmado, esta caminhada deve se ajustar ao descanso e ao transporte do grupo.',
'Westminster reúne referências centrais da história política e religiosa britânica. O Palácio de Westminster é a sede do Parlamento; sua arquitetura atual se desenvolveu após o incêndio do século XIX. A torre do relógio é conhecida mundialmente pela associação ao Big Ben, nome do grande sino.|St James’s Park conecta a área institucional a uma paisagem de lago, árvores e vistas para o eixo real. O contraste entre monumentos e parque ajuda a tornar a chegada mais leve, sem exigir uma sequência de visitas internas.',
[('Parlamento e torre do relógio','Observe o conjunto pela praça e pela ponte, com cuidado para não bloquear as passagens.'),('Westminster Abbey pelo exterior','Aprecie a fachada; visita interna é opcional e depende de ingresso e programação religiosa.'),('St James’s Park','Faça um circuito curto junto ao lago e escolha um ponto de pausa antes de voltar ao hotel ou seguir ao rio.')],
['Reduza ou adie o passeio se a chegada de Paris ocorrer tarde ou com atraso.','Não conte com troca da guarda: calendário e condições devem ser conferidos separadamente.','Use camadas de roupa e tenha opção de pausa coberta em novembro.'],
'Referência: estação Westminster. Ajuste o trajeto ao hotel e ao horário real de chegada.','2 a 3 horas, reduzível','Percurso externo; Parlamento, Big Ben e abadia têm modalidades de visita independentes.','A região tem travessias movimentadas; verifique acessos sem degraus nas estações e monumentos.','Da Westminster Bridge, procure o conjunto do Parlamento; no parque, fotografe vistas do lago sem se aproximar dos animais.',
['Palace of Westminster',"St James's Park"],[('Big Ben — Parlamento britânico','https://www.parliament.uk/about/living-heritage/building/palace/big-ben/'),('St James’s Park — Royal Parks','https://www.royalparks.org.uk/visit/parks/st-jamess-park')])

g('londres-southbank','South Bank às margens do Tâmisa','Londres','A cidade como promenade',
'Uma caminhada pela margem sul para ver pontes, espaços culturais e o perfil de Londres. A extensão deve acompanhar a disposição do grupo depois da chegada.',
'A margem sul do Tâmisa passou por grandes transformações ao longo do século XX. O Festival of Britain de 1951 ajudou a redefinir a área como espaço cultural, com o Royal Festival Hall como referência duradoura.|A caminhada atual conecta instituições culturais, áreas de lazer e vistas para a margem oposta. O valor do passeio está no percurso: acompanhar o rio permite perceber como estruturas históricas e equipamentos modernos compõem a paisagem londrina.',
[('Westminster Bridge e margem sul','Comece pelo panorama do Parlamento e siga pelo caminho de pedestres junto ao rio.'),('Área do Southbank Centre','Observe a arquitetura dos espaços culturais e confira o que está aberto sem compromisso de ingresso.'),('Pontes e ponto de retorno','Escolha uma ponte ou estação como limite do passeio. Estender até muito longe pode comprometer o descanso da chegada.')],
['O passeio é opcional se a manhã de chegada já tiver sido cansativa.','Confira vento e chuva antes de seguir por um trecho longo ao ar livre.','London Eye e atrações pagas não estão incluídos; decida separadamente.'],
'Referências: Westminster Bridge, Waterloo ou Embankment, conforme o sentido escolhido.','1h30 a 2 horas','Passeio externo; apresentações, rodas panorâmicas e exposições têm condições próprias.','A promenade tem trechos amplos, mas acessos às pontes e obras podem alterar o percurso sem degraus.','Explore reflexos no rio e a sequência das pontes; evite fotografar perto da borda em trechos congestionados.',
['South Bank','Royal Festival Hall'],[('História do Southbank Centre','https://www.southbankcentre.co.uk/about-us/history/'),('South Bank — turismo de Londres','https://www.visitlondon.com/things-to-do/london-areas/south-bank')])

g('londres-tower','Tower of London e Tower Bridge','Londres','Fortaleza, rio e engenharia',
'Uma manhã que aproxima dois marcos de épocas diferentes: a fortaleza ligada à monarquia e a ponte vitoriana que se tornou símbolo de Londres.',
'A Tower of London tem origem na conquista normanda e na construção da White Tower. Ao longo dos séculos, o conjunto exerceu funções de residência, fortaleza, prisão e lugar de guarda de tesouros e símbolos reais.|A Tower Bridge foi inaugurada no fim do século XIX para conciliar o tráfego urbano com a passagem de embarcações no Tâmisa. Suas torres e mecanismos contam uma história de engenharia distinta da fortaleza vizinha, apesar da aparência monumental que aproxima os dois edifícios.',
[('Tower of London','Escolha os espaços prioritários e consulte os percursos oficiais. Filas para as Joias da Coroa podem exigir reorganização da visita.'),('Exterior e margem do rio','Faça uma pausa fora da fortaleza e observe a relação entre muros, água e cidade.'),('Tower Bridge','Caminhe pela ponte no nível da rua. Passarelas superiores e salas das máquinas fazem parte de uma visita separada.')],
['Planeje a fortaleza como principal compromisso da manhã.','Visitas dos Yeoman Warders dependem do calendário e são oferecidas nas condições oficiais; confira idioma.','Não prometa ver a ponte abrir: consulte a programação se isso for uma prioridade.'],
'Referência: estação Tower Hill para a fortaleza; siga a pé até a ponte.','3 a 4 horas','Torre e exposição da Tower Bridge têm ingressos separados; confira áreas incluídas.','A fortaleza tem escadas e superfícies históricas; consulte percursos acessíveis de ambos os locais.','Da margem sul, a ponte rende um panorama completo; na fortaleza, siga as proibições de fotografia em áreas específicas.',
['Tower of London','Tower Bridge'],[('Tower of London — Historic Royal Palaces','https://www.hrp.org.uk/tower-of-london/'),('Tower Bridge — site oficial','https://www.towerbridge.org.uk/')])

g('londres-city','City e arredores de St Paul’s','Londres','Uma cidade que se reconstrói',
'Um percurso pela City para observar contrastes entre igrejas históricas, ruas de comércio e edifícios contemporâneos. A visita interna à catedral é uma escolha adicional.',
'A City preserva a memória do núcleo histórico de Londres e de suas funções comerciais e financeiras. O Grande Incêndio de 1666 alterou profundamente essa paisagem e abriu caminho para reconstruções que ainda definem sua imagem.|A atual Catedral de St Paul’s, projetada por Christopher Wren, é uma das expressões mais marcantes desse processo. Sua cúpula funciona como referência visual, inclusive em contraste com as construções recentes. A caminhada ajuda a ler Londres como uma cidade de substituições, permanências e recomeços.',
[('St Paul’s pelo exterior','Dê uma volta possível ao redor do edifício para perceber sua volumetria e a relação com as ruas próximas.'),('Interior, opcional','Se reservado, observe nave, mosaicos e espaços de memória. Galerias superiores exigem condições e tempo adicionais.'),('Millennium Bridge e entorno','Escolha um pequeno trecho até o rio para comparar a cúpula com a paisagem contemporânea.')],
['Depois da manhã na fortaleza, avalie se o grupo ainda quer outra visita interna.','Confira horários de visita e serviços religiosos da catedral.','Para vistas elevadas, verifique a quantidade de escadas e não trate a subida como obrigatória.'],
'Referências: St Paul’s ou chegada a pé a partir da região da Tower, conforme o percurso escolhido.','2 a 3 horas','Passeio externo livre de reserva; visita turística interna depende das condições oficiais.','A catedral e suas galerias têm acessos diferentes; consulte a rota adaptada e limite o circuito se necessário.','O eixo da Millennium Bridge oferece uma vista da cúpula; pare em local que não obstrua a passagem.',
["St Paul's Cathedral",'Millennium Bridge, London'],[('St Paul’s — história e visita','https://www.stpauls.co.uk/'),('City — turismo oficial','https://www.visitlondon.com/things-to-do/london-areas/city-of-london')])

g('londres-british','British Museum','Londres','Objetos, contextos e perguntas',
'Uma manhã para explorar culturas por meio de objetos e das histórias de suas coleções. Escolha duas ou três áreas e preserve espaço para leitura e conversa.',
'Fundado em 1753, o British Museum se desenvolveu como uma instituição dedicada a coleções de diversas partes do mundo. Seu acervo permite estabelecer relações entre sociedades e períodos, mas também levanta perguntas sobre formação das coleções, circulação de objetos e patrimônio cultural.|A Pedra de Roseta e as galerias de antiguidades são pontos conhecidos, enquanto o Great Court oferece uma referência arquitetônica para a orientação. Uma visita atenta pode combinar obras famosas com a leitura das informações sobre origem, função e trajetória dos objetos.',
[('Great Court e mapa','Use o pátio como ponto de orientação e defina um percurso pequeno antes de entrar nas galerias.'),('Duas ou três coleções','Selecione áreas conforme o interesse do grupo, consultando a disponibilidade das salas.'),('Objetos e proveniência','Leia a legenda além do nome da peça: origem, data, uso e contexto de incorporação enriquecem a visita.')],
['Consulte a reserva gratuita para a coleção permanente e as condições de exposições especiais.','Não programe uma lista longa de salas: o objetivo é compreender um recorte.','Combine um ponto de reencontro e uma pausa antes do passeio da tarde.'],
'Entrada principal de referência: Great Russell Street; confirme os acessos indicados pelo museu.','2h30 a 3 horas','Confira reserva e horários no site oficial; exposições especiais podem exigir bilhete próprio.','O museu informa entradas, elevadores e recursos adaptados; planeje o trajeto com o mapa de acessibilidade.','O Great Court permite fotografias de arquitetura; nas galerias, siga as regras e evite flash.',
['British Museum','Queen Elizabeth II Great Court'],[('British Museum — visita oficial','https://www.britishmuseum.org/visit'),('História e coleção','https://www.britishmuseum.org/about-us/british-museum-story')])

g('londres-covent','Covent Garden, Soho e despedida de Londres','Londres','Mercados, palcos e ruas vivas',
'Uma última tarde de bairro, com lojas, arquitetura e uma refeição cedo. A saída de Londres será às 06h do dia seguinte: o encerramento deve favorecer descanso e organização.',
'Covent Garden se desenvolveu ao redor de uma praça e de atividades de mercado. A antiga estrutura comercial se transformou, e o conjunto passou a reunir espaços de compras, cultura e apresentações, mantendo forte relação com a vida teatral do West End.|Soho acrescenta outra camada de história cultural, marcada por música, entretenimento, restaurantes e sucessivas comunidades. O passeio funciona como observação desse ambiente urbano, sem precisar encaixar compras extensas ou um espetáculo noturno antes de um embarque muito cedo.',
[('Piazza e mercado de Covent Garden','Observe os edifícios e percorra um trecho das galerias; respeite os espaços de artistas e circulação.'),('Caminho até Soho','Selecione ruas de interesse e mantenha o circuito compacto, conforme a disposição do grupo.'),('Jantar cedo e retorno','Escolha restaurante pelo cardápio e disponibilidade, depois volte para malas e confirmação do traslado.')],
['Defina um horário limite de retorno ao hotel antes de sair para passear.','Evite comprar ingresso de espetáculo noturno sem considerar o voo das 06h.','Confirme o transporte ao aeroporto na madrugada e o ponto de coleta das malas.'],
'Referências: Covent Garden, Leicester Square ou Tottenham Court Road, conforme o circuito.','2 a 3h30, incluindo refeição','Caminhada externa; espetáculos, experiências e restaurantes são contratados separadamente.','Há áreas cheias e pisos variados; escolha estações e acessos adequados à mobilidade do grupo.','Procure a arquitetura do mercado e detalhes das ruas; peça autorização antes de fotografar artistas de perto.',
['Covent Garden','Soho'],[('Covent Garden — site do destino','https://www.coventgarden.london/'),('West End — turismo oficial','https://www.visitlondon.com/things-to-do/london-areas/west-end')])

g('madrid-centro','Puerta del Sol, Plaza Mayor e centro','Madrid','Uma conexão com sabor de cidade',
'Um circuito compacto para o intervalo em Madrid, somente se o horário real de chegada, as malas e o retorno ao aeroporto permitirem. A prioridade continua sendo o voo das 22h.',
'Puerta del Sol é um dos grandes espaços de encontro de Madrid, ligado a referências como o quilômetro zero e o relógio da Casa de Correos. A praça sintetiza a função de centro urbano, comercial e simbólico.|A Plaza Mayor se consolidou no início do século XVII como uma grande praça regular associada à cidade da corte. Arcadas, fachadas e a estátua equestre de Felipe III dão unidade ao conjunto. A curta ligação entre as duas praças permite conhecer um recorte histórico sem atravessar a cidade inteira.',
[('Puerta del Sol','Localize as principais referências e estabeleça um ponto de encontro para o grupo antes de seguir.'),('Calle Mayor e Plaza Mayor','Caminhe pelo trecho central e percorra as arcadas para observar a praça de ângulos diferentes.'),('Pausa para almoço','Faça uma refeição simples e confira o horário disponível antes de decidir se haverá outro passeio.')],
['Só saia do aeroporto depois de confirmar tempo, bagagens e viabilidade do retorno.','Guarde as malas em serviço identificado; não há reserva de guarda-volume incluída.','Se o voo atrasar, elimine passeios opcionais em vez de reduzir a margem de embarque.'],
'Referência no centro: estação Sol. Calcule a ida e volta ao aeroporto com a rota atualizada.','2 a 3 horas, após confirmação do tempo disponível','Praças e caminhada externas; alimentação e guarda de bagagens são contratadas separadamente.','Predominam trechos de caminhada urbana; consulte elevadores do transporte e evite circuitos longos com malas.','Use as arcadas para enquadrar a Plaza Mayor e fotografe detalhes sem bloquear o fluxo de pedestres.',
['Puerta del Sol','Plaza Mayor, Madrid'],[('Puerta del Sol — turismo oficial','https://www.esmadrid.com/informacion-turistica/puerta-del-sol'),('Madrid clássico — turismo oficial','https://www.esmadrid.com/madrid-clasico')])

g('madrid-retiro','Retiro ou arredores do Palácio Real — opcional','Madrid','Escolha uma paisagem, preserve a volta',
'Uma alternativa curta para completar o dia em Madrid: jardins do Retiro ou o entorno do Palácio Real. São regiões diferentes; escolha apenas uma e mantenha o retorno ao aeroporto como compromisso principal.',
'O Retiro nasceu ligado ao lazer da corte e, ao longo do tempo, se transformou em parque público. Seu lago, caminhos e edifícios de épocas diferentes registram essa passagem de espaço real a lugar de convivência urbana.|O Palácio Real pertence a outro eixo da história monárquica madrilenha. O edifício atual foi construído após a perda do antigo Alcázar no século XVIII. Para esta conexão curta, a proposta é apreciar os arredores e a paisagem externa, sem pressupor uma visita completa aos salões.',
[('Opção A: Retiro','Escolha um acesso conveniente e um pequeno circuito junto ao lago. Não dependa da abertura de edifícios ou exposições.'),('Opção B: Palácio Real','Caminhe pela Plaza de Oriente e pelo entorno do palácio, observando a relação com a cidade e a Catedral da Almudena.'),('Retorno ao aeroporto','Encerre no horário definido e volte pela rota confirmada, sem acrescentar compras ou visitas de última hora.')],
['Não tente fazer Retiro e Palácio Real na mesma janela curta.','Consulte obras e áreas interditadas; fotografias históricas não garantem o cenário atual.','Cancele esta etapa se o horário de chegada, clima ou transporte reduzirem a margem de segurança.'],
'Retiro: região de Retiro/Estación del Arte. Palácio: região de Ópera. Escolha conforme o passeio anterior.','1 a 1h30, apenas se houver folga','Proposta externa; interior do Palácio Real e exposições têm ingresso e calendário próprios.','Jardins, distâncias e acessos de metrô variam; selecione o circuito mais simples para o grupo.','No Retiro, procure a paisagem do lago; na Plaza de Oriente, explore o conjunto do palácio sem entrar em áreas restritas.',
['Buen Retiro Park','Royal Palace of Madrid'],[('Retiro — turismo oficial','https://www.esmadrid.com/informacion-turistica/parque-del-retiro'),('Palácio Real — Patrimonio Nacional','https://www.patrimonionacional.es/visita/palacio-real-de-madrid')])

